begin;
create table public.rental_bundles(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,slug text not null,status text not null default 'draft' check(status in('draft','published','archived')),weekday_price_cents integer not null check(weekday_price_cents>=0),weekend_price_cents integer not null check(weekend_price_cents>=0),allow_promotional_discounts boolean not null default false,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_by uuid references auth.users(id),unique(business_id,slug));
create table public.rental_bundle_groups(id uuid primary key default gen_random_uuid(),bundle_id uuid not null references public.rental_bundles(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,name text not null,selection_mode text not null check(selection_mode in('fixed','customer_selectable')),min_selections integer not null default 1 check(min_selections>=0),max_selections integer not null default 1 check(max_selections>=min_selections),sort_order integer not null default 0);
create table public.rental_bundle_group_items(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.rental_bundle_groups(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,quantity integer not null default 1 check(quantity>0),upgrade_price_cents integer not null default 0 check(upgrade_price_cents>=0),sort_order integer not null default 0,unique(group_id,inventory_item_id));
create table public.rental_bundle_addons(id uuid primary key default gen_random_uuid(),bundle_id uuid not null references public.rental_bundles(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,quantity integer not null default 1 check(quantity>0),price_adjustment_cents integer not null default 0 check(price_adjustment_cents>=0),is_required boolean not null default false,sort_order integer not null default 0,unique(bundle_id,inventory_item_id));
create table public.booking_bundle_selections(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,booking_id uuid not null unique references public.bookings(id) on delete cascade,bundle_id uuid references public.rental_bundles(id) on delete set null,bundle_snapshot jsonb not null,selection_snapshot jsonb not null,weekday_price_cents integer not null,upgrade_cents integer not null default 0,addon_cents integer not null default 0,rental_subtotal_cents integer not null,created_at timestamptz not null default now());
create table public.booking_bundle_item_allocations(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,booking_id uuid not null references public.bookings(id) on delete cascade,booking_item_id uuid not null references public.booking_items(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,quantity integer not null check(quantity>0),allocated_rental_revenue_cents integer not null check(allocated_rental_revenue_cents>=0),list_price_cents integer not null check(list_price_cents>=0),unique(booking_item_id));
create index rental_bundles_public_idx on public.rental_bundles(business_id,status,slug);create index rental_bundle_groups_bundle_idx on public.rental_bundle_groups(business_id,bundle_id,sort_order);
alter table public.rental_bundles enable row level security;alter table public.rental_bundle_groups enable row level security;alter table public.rental_bundle_group_items enable row level security;alter table public.rental_bundle_addons enable row level security;alter table public.booking_bundle_selections enable row level security;alter table public.booking_bundle_item_allocations enable row level security;
create policy "members read rental bundles" on public.rental_bundles for select to authenticated using(public.is_business_member(business_id));create policy "managers manage rental bundles" on public.rental_bundles for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));
create policy "members read rental bundle groups" on public.rental_bundle_groups for select to authenticated using(public.is_business_member(business_id));create policy "members read rental bundle group items" on public.rental_bundle_group_items for select to authenticated using(public.is_business_member(business_id));create policy "members read rental bundle addons" on public.rental_bundle_addons for select to authenticated using(public.is_business_member(business_id));create policy "members read booking bundle selections" on public.booking_bundle_selections for select to authenticated using(public.is_business_member(business_id));create policy "members read booking bundle allocations" on public.booking_bundle_item_allocations for select to authenticated using(public.is_business_member(business_id));
create policy "managers manage rental bundle groups" on public.rental_bundle_groups for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));create policy "managers manage rental bundle group items" on public.rental_bundle_group_items for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));create policy "managers manage rental bundle addons" on public.rental_bundle_addons for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));

-- Uses the established reservation function inside this transaction.  The
-- package price is allocated proportionally by normal listing value solely for
-- tax/profitability line accounting; it never changes the customer total.
create or replace function public.create_bundle_booking(p_business_id uuid,p_bundle_id uuid,p_items jsonb,p_line_allocations jsonb,p_details jsonb,p_bundle_snapshot jsonb,p_selection_snapshot jsonb,p_weekday_price_cents integer,p_upgrade_cents integer,p_addon_cents integer,p_rental_subtotal_cents integer)
returns table(booking_id uuid,booking_number bigint) language plpgsql security definer set search_path=public as $$
declare v_created record; v_line jsonb; v_item_id uuid; v_price integer; v_total integer:=0;
begin
 if p_business_id is null or p_bundle_id is null or p_rental_subtotal_cents<0 then raise exception 'Invalid bundle booking.'; end if;
 if not exists(select 1 from public.rental_bundles where id=p_bundle_id and business_id=p_business_id and status='published') then raise exception 'Bundle is unavailable.'; end if;
 if (select count(*) from jsonb_array_elements(p_line_allocations))<>(select count(*) from jsonb_array_elements(p_items)) then raise exception 'Invalid bundle allocation.'; end if;
 for v_line in select value from jsonb_array_elements(p_line_allocations) loop v_item_id:=(v_line->>'inventoryItemId')::uuid;v_price:=(v_line->>'lineTotalCents')::integer;if v_price is null or v_price<0 or not exists(select 1 from jsonb_array_elements(p_items) x where (x->>'inventoryItemId')::uuid=v_item_id) then raise exception 'Invalid bundle allocation.';end if;v_total:=v_total+v_price;end loop;
 if v_total<>p_rental_subtotal_cents then raise exception 'Bundle allocation does not equal package price.';end if;
 select * into v_created from public.create_public_booking_quantities_timed(p_items,(p_details->>'rentalDate')::date,(p_details->>'rentalEndDate')::date,p_details->>'firstName',p_details->>'lastName',p_details->>'email',p_details->>'phone',(p_details->>'startTime')::time,(p_details->>'endTime')::time,p_details->>'address',p_details->>'city',p_details->>'zipCode',coalesce(p_details->>'notes',''));
 insert into public.booking_bundle_item_allocations(business_id,booking_id,booking_item_id,inventory_item_id,quantity,allocated_rental_revenue_cents,list_price_cents) select p_business_id,v_created.booking_id,bi.id,bi.inventory_item_id,bi.quantity,(a.value->>'lineTotalCents')::integer,bi.unit_price_cents*bi.quantity from public.booking_items bi join jsonb_array_elements(p_line_allocations) a on bi.inventory_item_id=(a.value->>'inventoryItemId')::uuid where bi.booking_id=v_created.booking_id;
 insert into public.booking_bundle_selections(business_id,booking_id,bundle_id,bundle_snapshot,selection_snapshot,weekday_price_cents,upgrade_cents,addon_cents,rental_subtotal_cents) values(p_business_id,v_created.booking_id,p_bundle_id,p_bundle_snapshot,p_selection_snapshot,p_weekday_price_cents,p_upgrade_cents,p_addon_cents,p_rental_subtotal_cents);
 return query select v_created.booking_id,v_created.booking_number;
end $$;
revoke all on function public.create_bundle_booking(uuid,uuid,jsonb,jsonb,jsonb,jsonb,jsonb,integer,integer,integer,integer) from public,anon,authenticated;grant execute on function public.create_bundle_booking(uuid,uuid,jsonb,jsonb,jsonb,jsonb,jsonb,integer,integer,integer,integer) to service_role;
commit;
